def compute(vars):
    v1 = vars["v1"]
    v2 = vars["v2"]
    if v2 == 0:
        return None
    change_ratio = (v1 - v2) / v2 * 100
    return {
        "value": change_ratio,
        "trace": {
            "v1": v1,
            "v2": v2,
            "change_ratio": change_ratio,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "percent"
            }
        }
    }
